const pad = n => String(n).padStart(2, '0');
const dstr = d => d.getFullYear() + '-' + pad(d.getMonth()+1) + '-' + pad(d.getDate());
const esc = t => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;');
const s = new Date(); const e = new Date(); e.setDate(e.getDate() + 45);
const xhr = new XMLHttpRequest();
xhr.open('POST', '/api/products/productionseasons', false);
xhr.setRequestHeader('Content-Type', 'application/json');
xhr.setRequestHeader('Accept', 'application/json, text/javascript, */*; q=0.01');
xhr.setRequestHeader('X-Requested-With', 'XMLHttpRequest');
xhr.send(JSON.stringify({productionSeasonIdFilter: [], keywordIds: null, keywords: [],
  startDate: dstr(s) + 'T00:00', endDate: dstr(e) + 'T23:59'}));
if (xhr.status === 200) {
  const data = JSON.parse(xhr.responseText);
  /* Tessitura cuts titles at 30 characters (A CHRONICLE OF AMOROUS INCIDEN = ...ACCIDENTS).
     filmforum.org (CORS *) lists each film as a JSON-LD ScreeningEvent whose offer URL is
     my.filmforum.org/events/<slug>, the production's own slug: map cut titles through it. */
  const CAP = 30;
  const slugOf = u => String(u || '').replace(/\/+$/, '').split('/').pop();
  const publicTitles = {};
  if ((data.productions || []).some(p => (p.productionTitle || '').trim().length >= CAP)) {
    ['https://filmforum.org/now_playing', 'https://filmforum.org/coming_soon'].forEach(page => {
      try {
        const r = new XMLHttpRequest(); r.open('GET', page, false); r.send();
        if (r.status !== 200) return;
        const doc = new DOMParser().parseFromString(r.responseText, 'text/html');
        doc.querySelectorAll('script[type="application/ld+json"]').forEach(tag => {
          let ld; try { ld = JSON.parse(tag.textContent); } catch (err) { return; }
          const walk = x => {
            if (Array.isArray(x)) { x.forEach(walk); return; }
            if (!x || typeof x !== 'object') return;
            if (x['@type'] === 'ScreeningEvent' && x.name) {
              [].concat(x.offers || []).forEach(o => {
                if (o && /\/events\//.test(o.url || '')) {
                  const k = slugOf(o.url);
                  if (!publicTitles[k]) publicTitles[k] = x.name.replace(/<br\s*\/?>/gi, ' ').replace(/\s+/g, ' ').trim();
                }
              });
            }
            Object.values(x).forEach(walk);
          };
          walk(ld);
        });
      } catch (err) {}
    });
  }
  const parts = [];
  (data.productions || []).forEach(prod => {
    const short = (prod.productionTitle || '').trim();
    if (!short) return;
    let name = short, note = '';
    if (short.length >= CAP) {
      const full = publicTitles[slugOf(prod.productionSeasonActionUrl)];
      if (full) name = full;
      else note = '<div>Title cut at 30 characters by the ticketing system</div>';
    }
    const days = {};
    let href = '';
    (prod.performances || []).forEach(perf => {
      if (perf.isPerformanceVisible === false) return;
      const iso = (perf.iso8601DateString || '').slice(0, 10);
      if (!iso) return;
      if (!href && perf.actionUrl) href = perf.actionUrl;
      const t = (perf.performanceTitle || '').trim();
      (days[iso] = days[iso] || []).push((perf.displayTime || '') + (t && t !== short ? ' (' + t + ')' : ''));
    });
    const dates = Object.keys(days).sort();
    if (!dates.length) return;
    for (let i = 0; i < dates.length; i += 3) {
      const rows = dates.slice(i, i + 3).map(d => '<div>' + d + ': ' + esc(days[d].join(', ')) + '</div>');
      parts.push('<div><h3><a href="' + href + '">' + esc(name) + '</a></h3>' + note + '<div>View Event Details</div><div>Showtimes:</div>' + rows.join(' ') + '</div>');
    }
  });
  if (parts.length) { document.body.innerHTML = '<h1>Film Forum - Complete Showtime Calendar. Each block lists ONE film with some of its showtimes; the SAME film may appear in multiple blocks - extract every dated showtime.</h1>' + parts.join(' '); }
}
